-- Gives the contacts and groups an owner. Generated by drizzle-kit, the order of the steps is
-- arranged by hand: the column is added empty, the existing data gets an owner, and only then the
-- column becomes required.
-- The address of the owner is not in this file (the repository is public): scripts/migrate.ts passes
-- OWNER_EMAIL as the setting app.owner_email of its connection. Migrations of one run share a
-- transaction, so if this one fails nothing of 0003 and 0004 stays in the database.

-- 1. The new columns, still empty
ALTER TABLE "contacts" ADD COLUMN "owner_id" text;--> statement-breakpoint
ALTER TABLE "groups" ADD COLUMN "owner_id" text;--> statement-breakpoint

-- 2. If there is data, it all goes to the user with the address OWNER_EMAIL: the user that exists,
-- or a new one. No data (a new database): nothing to do, the address is not needed.
DO $$
DECLARE
  owner_email text := lower(trim(coalesce(current_setting('app.owner_email', true), '')));
  owner_user_id text;
BEGIN
  IF EXISTS (SELECT 1 FROM "contacts") OR EXISTS (SELECT 1 FROM "groups") THEN
    IF owner_email = '' THEN
      RAISE EXCEPTION 'OWNER_EMAIL is not set: existing contacts and groups need an owner';
    END IF;

    SELECT "id" INTO owner_user_id FROM "users" WHERE lower("email") = owner_email;
    IF owner_user_id IS NULL THEN
      owner_user_id := gen_random_uuid()::text;
      INSERT INTO "users" ("id", "name", "email", "email_verified")
      VALUES (owner_user_id, '', owner_email, true);
    END IF;

    UPDATE "contacts" SET "owner_id" = owner_user_id;
    UPDATE "groups" SET "owner_id" = owner_user_id;
  END IF;
END $$;--> statement-breakpoint

-- 3. Now every row has an owner: the column is required, with a link to the user
ALTER TABLE "contacts" ALTER COLUMN "owner_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "groups" ALTER COLUMN "owner_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "contacts" ADD CONSTRAINT "contacts_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "groups" ADD CONSTRAINT "groups_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint

-- 4. Group names are unique within one owner, not in the whole database
DROP INDEX "groups_name_unique_idx";--> statement-breakpoint
CREATE UNIQUE INDEX "groups_owner_name_unique_idx" ON "groups" USING btree ("owner_id",replace(lower("name"), 'ё', 'е'));--> statement-breakpoint
CREATE INDEX "contacts_owner_id_idx" ON "contacts" USING btree ("owner_id");
